      const F = fr.map((x) => ({ ...x, hit: x.keys.find((k) => norm(k).includes(s)) })).filter((x) => x.hit), P = pls.filter((x) => x.k.includes(s)).sort((a, b) => (b.k.startsWith(s) - a.k.startsWith(s)) || (b.p.tot || 0) - (a.p.tot || 0)).slice(0, 12);
