        (P.length ? `<h3 class="pi-h">Players</h3>${P.map((x) => `<button class="sr-r" data-open="${x.pid}">${x.p.tm ? nflBadge(x.p.tm) : '<span class="nb">FA</span>'}<span><b>${esc(x.p.n)}</b><small>${esc(x.p.elig.join('/') || x.p.pos || '')}${x.p.own ? ' · ' + esc(c.byRoster[x.p.own.roster_id].manager) : ' · not on a league roster'}${x.p.rk ? ' · ' + Object.entries(x.p.rk).map(([a, b]) => a + b).join(', ') : ''}</small></span></button>`).join('')}` : '') || `<p class="pi-note">Nothing matches “${esc(q.value)}”. Players appear here once they have been on a league roster this season.</p>`;
